import { Pencil } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Textarea } from '@/components/ui/form';
import { useNotifications } from '@/components/ui/notifications';

import {
  useUpdateComment,
  updateCommentInputSchema,
} from '../api/update-comment';

type EditCommentProps = {
  id: string;
  discussionId: string;
  initialBody: string;
};

export const EditComment = ({ id, discussionId, initialBody }: EditCommentProps) => {
  const { addNotification } = useNotifications();
  const editCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  return (
    <FormDrawer
      isDone={editCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<Pencil className="size-4" />}>
          Edit
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={editCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
        >
          Update Comment
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          editCommentMutation.mutate({
            commentId: id,
